import boto3

from vision_client import get_vision_client
from vision_models import normalize_image_safety


def score_image_safety(payload, config=None):
    config = config or {}
    client = get_vision_client(config)
    response = client.detect_moderation_labels(
        Image={"Bytes": payload["image_bytes"]},
    )
    labels = response["ModerationLabels"]
    safety_score = sum([label["Confidence"] for label in labels]) / len(labels) if labels else 0
    return normalize_image_safety(safety_score)

import boto3


def get_vision_client(config=None):
    config = config or {}
    region = config.get("region", "us-west-2")
    return boto3.client("rekognition", region_name=region)

def normalize_image_description(description):
    return description.lower()


def normalize_image_text(text):
    return text.strip()


def normalize_image_safety(safety_score):
    return safety_score

import boto3

from vision_client import get_vision_client
from vision_models import normalize_image_summary


def image_summary(payload, config=None):
    config = config or {}
    client = get_vision_client(config)
    labels = client.detect_labels(
        Image={"Bytes": payload["image_bytes"]},
        MaxLabels=int(config.get("max_labels", 10)),
    )["Labels"]
    text = client.detect_text(
        Image={"Bytes": payload["image_bytes"]},
    )["TextDetections"]
    summary = " ".join([label["Name"] for label in labels] + [detection["DetectedText"] for detection in text])
    return normalize_image_summary(summary)

import boto3

from vision_client import get_vision_client
from vision_models import normalize_visual_safety_text


def visual_safety_text(payload, config=None):
    config = config or {}
    client = get_vision_client(config)
    labels = client.detect_labels(
        Image={"Bytes": payload["image_bytes"]},
        MaxLabels=int(config.get("max_labels", 10)),
    )["Labels"]
    unsafe_text = [label["Name"] for label in labels if label["Confidence"] > 80]
    return normalize_visual_safety_text(" ".join(unsafe_text))
